const data = $input.first().json.data;
if (!data || !data.lactateData || data.lactateData.length < 3) {
  throw new Error('Zu wenig Laktat-Messpunkte (min. 3 erforderlich)');
}
const methods = ['dickhuth', 'dmax', 'mader', 'moddmax'];
return methods.map(method => ({
  json: {
    targetMethod: method,
    sessionId: data.sessionId,
    customerId: data.customerId,
    customerName: data.customerName,
    unit: data.unit || 'watt',
    zoneModel: data.zoneModel || '5-zones',
    stepCount: data.stepCount || data.lactateData.length,
    testDevice: data.testDevice || 'bike',
    lactateData: data.lactateData,
    currentThresholds: data.currentThresholds || { lt1: null, lt2: null },
    currentMethod: data.currentMethod
  }
}));

parameters.text:
=Apply the {{ $json.targetMethod }} method to this lactate step test.

Unit: {{ $json.unit }}
Device: {{ $json.testDevice }}
Stages: {{ $json.stepCount }}
Zone model context: {{ $json.zoneModel }}

Lactate data (power, lactate mmol/L, heartRate bpm):
{{ JSON.stringify($json.lactateData) }}

Reference thresholds (current, may be null):
LT1: {{ JSON.stringify($json.currentThresholds.lt1) }}
LT2: {{ JSON.stringify($json.currentThresholds.lt2) }}

Apply ONLY the {{ $json.targetMethod }} method. Return the JSON result.

parameters.jsCode:
const allItems = $input.all();
const results = [];

for (const item of allItems) {
  const out = item.json;
  let parsed = null;

  if (out.lt1 !== undefined || out.lt2 !== undefined) {
    parsed = out;
  } else if (typeof out.output === 'string') {
    const m = out.output.match(/\{[\s\S]*\}/);
    if (m) {
      try { parsed = JSON.parse(m[0]); } catch(e) {}
    }
  } else if (typeof out.text === 'string') {
    const m = out.text.match(/\{[\s\S]*\}/);
    if (m) {
      try { parsed = JSON.parse(m[0]); } catch(e) {}
    }
  }

  if (parsed && (parsed.lt1 || parsed.lt2)) {
    results.push({
      method: parsed.method || 'unknown',
      lt1: parsed.lt1 || null,
      lt2: parsed.lt2 || null,
      confidence: parsed.confidence ?? 0.5,
      reasoning: parsed.reasoning || ''
    });
  }
}

if (results.length === 0) {
  throw new Error('Alle Spezialistenagenten haben kein valides Ergebnis geliefert');
}

const ctx = allItems[0].json;
return [{
  json: {
    methodResults: results,
    unit: ctx.unit,
    zoneModel: ctx.zoneModel,
    testDevice: ctx.testDevice,
    lactateData: ctx.lactateData,
    sessionId: ctx.sessionId,
    customerId: ctx.customerId,
    customerName: ctx.customerName
  }
}];

