parameters.jsCode:
const out = $input.first().json;
let r = null;

if (out.lt1 !== undefined || out.lt2 !== undefined) {
  r = out;
} else if (typeof out.output === 'string') {
  const m = out.output.match(/\{[\s\S]*\}/);
  if (m) { try { r = JSON.parse(m[0]); } catch(e) {} }
} else if (typeof out.text === 'string') {
  const m = out.text.match(/\{[\s\S]*\}/);
  if (m) { try { r = JSON.parse(m[0]); } catch(e) {} }
}

if (!r || (!r.lt1 && !r.lt2)) {
  return [{ json: {
    success: false,
    lt1: null, lt2: null, method: null,
    reasoning: (typeof out.output === 'string' ? out.output : null) || (typeof out.text === 'string' ? out.text : null),
    message: 'Compose-Agent hat keine validen Schwellenwerte zurueckgegeben'
  }}];
}

return [{ json: {
  success: true,
  lt1: r.lt1 || null,
  lt2: r.lt2 || null,
  method: r.method || 'composed',
  reasoning: r.reasoning || null
}}];

const errorMsg = $execution?.customData?.error?.message || $input.first()?.json?.error?.message || 'Unbekannter Workflow-Fehler';
return [{ json: {
  success: false,
  lt1: null, lt2: null, method: null,
  reasoning: null,
  message: errorMsg
}}];
